// Command for unassigning a Security to a Trade
//-----------------------------------------------------------
data class UnAssignSecurityFromTradeCommand(@TargetAggregateIdentifier  val tradeId: UUID )
//-----------------------------------------------------------
// Command for assigning a InvestmentAccount to a Trade
//-----------------------------------------------------------
data class AssignInvestmentAccountToTradeCommand(@TargetAggregateIdentifier  val tradeId: UUID, val assignment: InvestmentAccount )

//-----------------------------------------------------------
// Command for unassigning a InvestmentAccount to a Trade
//-----------------------------------------------------------
data class UnAssignInvestmentAccountFromTradeCommand(@TargetAggregateIdentifier  val tradeId: UUID )

// multiple association commands

//-----------------------------------------------------------
// Command for producing an instance of a ExchangeRate
//-----------------------------------------------------------
data class CreateExchangeRateCommand(
    @TargetAggregateIdentifier var exchangeRateId: UUID? = null,
    var baseCurrency: String? = null,
    var quoteCurrency: String? = null,
    var rate: java.math.BigDecimal? = null,
         @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "asOf_value"))
    )
    var asOf: DateTime? = null,
    var source: String? = null
)
//-----------------------------------------------------------
// Command for modifying an instance of a ExchangeRate
//-----------------------------------------------------------
data class UpdateExchangeRateCommand(
    @TargetAggregateIdentifier var exchangeRateId: UUID? = null,
    var baseCurrency: String? = null,
    var quoteCurrency: String? = null,
    var rate: java.math.BigDecimal? = null,
         @AttributeOverrides(
      AttributeOverride( name = "value", column = Column(name = "asOf_value"))
    )
    var asOf: DateTime? = null,
    var source: String? = null,
    var usedByQuotes:  Set<FXQuote>? = null
)
//-----------------------------------------------------------
// Command for removing an instance of a ExchangeRate
//-----------------------------------------------------------
data class DeleteExchangeRateCommand(@TargetAggregateIdentifier  var exchangeRateId: UUID? = null)

// single association commands

// multiple association commands
//-----------------------------------------------------------
// Command for adding a FXQuote to a ExchangeRate
//-----------------------------------------------------------
data class AssignUsedByQuotesToExchangeRateCommand(@TargetAggregateIdentifier  val exchangeRateId: UUID, val addTo: FXQuote )
//-----------------------------------------------------------
// Command for removing a FXQuote from a ExchangeRate
//-----------------------------------------------------------
data class RemoveUsedByQuotesFromExchangeRateCommand(@TargetAggregateIdentifier  val exchangeRateId: UUID, val removeFrom: FXQuote )



